class FoodItem {
  final String id, name;
  final double kcal, protein, fat, carbs, fiber;
  const FoodItem(this.id, this.name, this.kcal, this.protein, this.fat, this.carbs, this.fiber);
  Map<String,dynamic> toJson()=>{'id':id,'name':name,'kcal':kcal,'protein':protein,'fat':fat,'carbs':carbs,'fiber':fiber};
  factory FoodItem.fromJson(Map<String,dynamic> j)=>FoodItem(j['id'],j['name'],(j['kcal'] as num).toDouble(),(j['protein'] as num).toDouble(),(j['fat'] as num).toDouble(),(j['carbs'] as num).toDouble(),(j['fiber'] as num).toDouble());
}
class DiaryItem {
  final String id, meal, time; final FoodItem food; final double grams;
  const DiaryItem({required this.id,required this.meal,required this.food,required this.grams,required this.time});
  double get kcal=>food.kcal*grams/100; double get protein=>food.protein*grams/100; double get fat=>food.fat*grams/100; double get carbs=>food.carbs*grams/100; double get fiber=>food.fiber*grams/100;
  Map<String,dynamic> toJson()=>{'id':id,'meal':meal,'food':food.toJson(),'grams':grams,'time':time};
  factory DiaryItem.fromJson(Map<String,dynamic> j)=>DiaryItem(id:j['id'],meal:j['meal'],food:FoodItem.fromJson(Map<String,dynamic>.from(j['food'])),grams:(j['grams'] as num).toDouble(),time:j['time']);
}

