  Future<void> _addCustom() async{final n=TextEditingController(),k=TextEditingController(),p=TextEditingController(),f=TextEditingController(),c=TextEditingController(),fi=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Свой продукт'),content:SingleChildScrollView(child:Column(children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Название')),TextField(controller:k,decoration:const InputDecoration(labelText:'Ккал / 100 г')),TextField(controller:p,decoration:const InputDecoration(labelText:'Белок / 100 г')),TextField(controller:f,decoration:const InputDecoration(labelText:'Жиры / 100 г')),TextField(controller:c,decoration:const InputDecoration(labelText:'Углеводы / 100 г')),TextField(controller:fi,decoration:const InputDecoration(labelText:'Клетчатка / 100 г'))])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Отмена')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Сохранить'))]));if(ok!=true||n.text.trim().isEmpty)return;setState(()=>customFoods.add(FoodItem('custom_${DateTime.now().microsecondsSinceEpoch}',n.text.trim(),double.tryParse(k.text.replaceAll(',','.'))??0,double.tryParse(p.text.replaceAll(',','.'))??0,double.tryParse(f.text.replaceAll(',','.'))??0,double.tryParse(c.text.replaceAll(',','.'))??0,double.tryParse(fi.text.replaceAll(',','.'))??0)));await _saveFoods();}
  Future<void> _addWater() async{setState(()=>water+=.25);await _num('water',water);}
  Future<void> _addWeight() async{final c=TextEditingController(text:weight.toStringAsFixed(1));final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Вес'),content:TextField(controller:c,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(suffixText:'кг')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Отмена')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Сохранить'))]));if(ok!=true)return;final v=double.tryParse(c.text.replaceAll(',','.'));if(v==null||v<30||v>300)return;setState(()=>weight=v);await _num('weight',v);}
}

class ProgressLine extends StatelessWidget{final String label,text;final double value;const ProgressLine({super.key,required this.label,required this.value,required this.text});@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.only(bottom:15),child:Column(children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(label,style:const TextStyle(fontWeight:FontWeight.w800,color:ink)),Text(text,style:const TextStyle(color:muted))]),const SizedBox(height:6),ClipRRect(borderRadius:BorderRadius.circular(8),child:LinearProgressIndicator(value:value.clamp(0,1),minHeight:8,color:green,backgroundColor:mint))]));}
